with valid_web_events as (select * from web_events where duration_sec between 189 and 322 and to_date(event_time) >= '2024-12-01'), summary as (select year(event_time) as event_year, sort_array(collect_set(event_type)) as event_type_list, min(duration_sec) as min_duration_sec from valid_web_events group by year(event_time)) select * from summary where min_duration_sec >= 200 order by event_year desc;
